from pathlib import Path
import ast,json,time
from sage.all import GF,PolynomialRing
P=Path(__file__).resolve().parent/'data';t=time.monotonic();a=ast.literal_eval((P/'cyclic42_A11_seven/model_bases.txt').read_text().replace('[*','[').replace('*]',']'));n,fp=a[:2];k=GF(5);R=PolynomialRing(k,'x');K=R.fraction_field();S=PolynomialRing(k,2,names=('x','y'));x,y=S.gens();assert all(c[1]==[1]for c in fp);F=sum(sum(S(v)*x**j for j,v in enumerate(c[0]))*y**i for i,c in enumerate(fp));res=F.resultant(F.derivative(y),y);assert res!=0;rr=R(res.univariate_polynomial());lc=R(fp[-1][0]);disc=(-1)**(n*(n-1)//2)*K(rr)/K(lc)**(2*n-1);out=dict(complete=True,degree=n,resultant=list(map(int,rr)),leading_coefficient=list(map(int,lc)),discriminant_numerator=list(map(int,disc.numerator())),discriminant_denominator=list(map(int,disc.denominator())));(P/'direct_rr_discriminant_certificate.json').write_text(json.dumps(out,indent=2)+'\n');print('C242_GENUS25_EXACT_DISCRIMINANT_PASS',len(rr.list()),'seconds',time.monotonic()-t,flush=True)
